mapper.select:
SELECT a.id, a.title, a.cover, a.excerpt, a.views AS view_count, a.likes AS like_count, a.create_time AS created_time, ca.sort_order AS sort_order, a.author_id as user_id, pu.nickname AS author_name, pu.username AS author_username FROM portal_column_article ca INNER JOIN portal_article a ON a.id = ca.article_id LEFT JOIN portal_user pu ON pu.id = a.author_id WHERE ca.column_id = #{columnId}
AND a.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY ca.sort_order ASC, ca.created_time ASC
